 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Mark trailing background of the first component row where the pattern appears.
    # Demos place 1s to the right of a particular repeated horizontal motif.
    for r, row in enumerate(grid):
        if r > 0 and any(v != row[0] for v in row):
            # final run of background after the last foreground cell
            bg = row[0]
            last = max((c for c, v in enumerate(row) if v != bg), default=-1)
            if last >= 0 and last + 1 < len(row) and all(v == bg for v in row[last+1:]):
                for c in range(last+1, len(row)):
                    out[r][c] = 1
                break
    return out
"
}

